import { db } from "@/lib/db";
import { getSetting } from "@/lib/settings";

/**
 * Plain (non-action) aggregation helpers for the visitor-analytics admin page.
 * These are read-only Prisma queries over the `Visit` table. Everything is
 * scoped to short recent windows and small `take` limits so the page stays
 * cheap even as the visit log grows.
 */

const DAY = 86_400_000;

/** IPs the admin has chosen to exclude from analytics (their own IP, office IP,
 *  a noisy bot) so the numbers reflect ACTUAL public traffic. Stored as a
 *  comma-separated setting. */
export async function excludedIps(): Promise<string[]> {
  const raw = (await getSetting("analytics_excluded_ips")) ?? "";
  return raw.split(",").map((s) => s.trim()).filter(Boolean);
}

/** Prisma where-fragment dropping excluded IPs. Empty object when none are set,
 *  so it spreads harmlessly into any `where`. */
async function ipEx(): Promise<{ ip?: { notIn: string[] } }> {
  const e = await excludedIps();
  return e.length ? { ip: { notIn: e } } : {};
}

/** Distinct client IPs seen in the last `minutes` — our "live visitors now" gauge. */
export async function liveVisitors(minutes = 5): Promise<number> {
  const since = new Date(Date.now() - minutes * 60_000);
  const rows = await db.visit.findMany({
    where: { createdAt: { gte: since }, ...(await ipEx()) },
    distinct: ["ip"],
    select: { ip: true },
  });
  return rows.length;
}

/** Total page views since local midnight. */
export async function todayViews(): Promise<number> {
  const start = new Date();
  start.setHours(0, 0, 0, 0);
  return db.visit.count({ where: { createdAt: { gte: start }, ...(await ipEx()) } });
}

/** Total page views in the trailing `days` window (default 7d). */
export async function viewsInWindow(days = 7): Promise<number> {
  const since = new Date(Date.now() - days * DAY);
  return db.visit.count({ where: { createdAt: { gte: since }, ...(await ipEx()) } });
}

/** Distinct visitors (by IP) in the trailing `days` window. */
export async function uniqueVisitors(days = 7): Promise<number> {
  const since = new Date(Date.now() - days * DAY);
  const rows = await db.visit.findMany({
    where: { createdAt: { gte: since }, ...(await ipEx()) },
    distinct: ["ip"],
    select: { ip: true },
  });
  return rows.length;
}

/** Reduce a raw referrer URL to a bare hostname for grouping/display. */
export function referrerHost(ref: string | null | undefined): string | null {
  if (!ref) return null;
  try {
    const h = new URL(ref).hostname.replace(/^www\./, "");
    return h || null;
  } catch {
    const trimmed = ref.trim();
    return trimmed ? trimmed.slice(0, 60) : null;
  }
}

export type Counted = { label: string; count: number };

/** Top external referrer hosts over the trailing `days` window. */
export async function topReferrers(days = 7, limit = 8): Promise<Counted[]> {
  const since = new Date(Date.now() - days * DAY);
  const rows = await db.visit.findMany({
    where: { createdAt: { gte: since }, referrer: { not: null }, ...(await ipEx()) },
    select: { referrer: true },
    take: 5000,
    orderBy: { createdAt: "desc" },
  });
  const tally = new Map<string, number>();
  for (const r of rows) {
    const host = referrerHost(r.referrer);
    if (!host) continue;
    tally.set(host, (tally.get(host) ?? 0) + 1);
  }
  return [...tally.entries()]
    .map(([label, count]) => ({ label, count }))
    .sort((a, b) => b.count - a.count)
    .slice(0, limit);
}

/** Top countries among geocoded visits over the trailing `days` window. */
export async function topCountries(days = 30, limit = 8): Promise<Counted[]> {
  const since = new Date(Date.now() - days * DAY);
  const grp = await db.visit.groupBy({
    by: ["country"],
    where: { createdAt: { gte: since }, geocoded: true, country: { not: null }, ...(await ipEx()) },
    _count: { _all: true },
  });
  return grp
    .map((g) => ({ label: g.country as string, count: g._count._all }))
    .sort((a, b) => b.count - a.count)
    .slice(0, limit);
}

/** Top cities among geocoded visits over the trailing `days` window. */
export async function topCities(days = 30, limit = 8): Promise<Counted[]> {
  const since = new Date(Date.now() - days * DAY);
  const rows = await db.visit.findMany({
    where: { createdAt: { gte: since }, geocoded: true, city: { not: null }, ...(await ipEx()) },
    select: { city: true, country: true },
    take: 5000,
    orderBy: { createdAt: "desc" },
  });
  const tally = new Map<string, number>();
  for (const r of rows) {
    const label = r.country ? `${r.city}, ${r.country}` : (r.city as string);
    tally.set(label, (tally.get(label) ?? 0) + 1);
  }
  return [...tally.entries()]
    .map(([label, count]) => ({ label, count }))
    .sort((a, b) => b.count - a.count)
    .slice(0, limit);
}

export type RecentVisit = {
  id: string;
  ip: string;
  path: string;
  referrer: string | null;
  kind: string;
  country: string | null;
  region: string | null;
  city: string | null;
  createdAt: Date;
};

/** Most recent visits for the live activity table. */
export async function recentVisits(limit = 40): Promise<RecentVisit[]> {
  return db.visit.findMany({
    where: { ...(await ipEx()) },
    orderBy: { createdAt: "desc" }, // already newest-first (sorted by date)
    take: limit,
    select: {
      id: true,
      ip: true,
      path: true,
      referrer: true,
      kind: true,
      country: true,
      region: true,
      city: true,
      createdAt: true,
    },
  });
}

// ---- Date-range traffic feed ----
// The dashboard above uses fixed trailing windows; this feed lets the admin pick
// an explicit date range and sort direction, so they can answer "what happened
// on/between these days" rather than only "the last N days". It reuses the same
// IP-exclusion (`ipEx`) as everything else, so hidden IPs stay hidden here too.

export type FeedKind = "all" | "marketing" | "portal";
export type FeedDir = "desc" | "asc";

export type FeedFilter = {
  /** Inclusive start day, `yyyy-mm-dd` (local). */
  from?: string;
  /** Inclusive end day, `yyyy-mm-dd` (local). */
  to?: string;
  kind?: FeedKind;
  /** Sort by date: newest-first (`desc`, default) or oldest-first (`asc`). */
  dir?: FeedDir;
  limit?: number;
};

const YMD = /^\d{4}-\d{2}-\d{2}$/;

/** Start-of-day Date for a `yyyy-mm-dd` string, or undefined if absent/invalid. */
function dayStart(s?: string): Date | undefined {
  if (!s || !YMD.test(s)) return undefined;
  const d = new Date(`${s}T00:00:00`);
  return Number.isNaN(d.getTime()) ? undefined : d;
}

/** End-of-day (inclusive) Date for a `yyyy-mm-dd` string, or undefined. */
function dayEnd(s?: string): Date | undefined {
  if (!s || !YMD.test(s)) return undefined;
  const d = new Date(`${s}T23:59:59.999`);
  return Number.isNaN(d.getTime()) ? undefined : d;
}

/** Build the shared `where` for the feed (date range + kind + IP exclusion). */
async function feedWhere(f: FeedFilter) {
  const gte = dayStart(f.from);
  const lte = dayEnd(f.to);
  const where: {
    ip?: { notIn: string[] };
    kind?: string;
    createdAt?: { gte?: Date; lte?: Date };
  } = { ...(await ipEx()) };
  if (gte || lte) where.createdAt = { ...(gte ? { gte } : {}), ...(lte ? { lte } : {}) };
  if (f.kind && f.kind !== "all") where.kind = f.kind;
  return where;
}

/**
 * Visits within an explicit date range, sorted by date. Capped by `limit`
 * (default 100, hard max 500) so the page stays cheap no matter the range.
 */
export async function visitFeed(f: FeedFilter): Promise<RecentVisit[]> {
  const limit = Math.min(Math.max(f.limit ?? 100, 1), 500);
  return db.visit.findMany({
    where: await feedWhere(f),
    orderBy: { createdAt: f.dir === "asc" ? "asc" : "desc" },
    take: limit,
    select: {
      id: true,
      ip: true,
      path: true,
      referrer: true,
      kind: true,
      country: true,
      region: true,
      city: true,
      createdAt: true,
    },
  });
}

/** Total matching visits for the current feed filter (for the result count). */
export async function visitFeedCount(f: FeedFilter): Promise<number> {
  return db.visit.count({ where: await feedWhere(f) });
}

export type GlobePoint = {
  lat: number;
  lng: number;
  city: string | null;
  country: string | null;
  kind: string;
};

/**
 * Recent geocoded visits with coordinates, for the activity globe. Capped so the
 * canvas stays performant regardless of how much traffic has accumulated.
 */
export async function globePoints(days = 7, limit = 300): Promise<GlobePoint[]> {
  const since = new Date(Date.now() - days * DAY);
  const rows = await db.visit.findMany({
    where: {
      createdAt: { gte: since },
      geocoded: true,
      lat: { not: null },
      lng: { not: null },
      ...(await ipEx()),
    },
    orderBy: { createdAt: "desc" },
    take: limit,
    select: { lat: true, lng: true, city: true, country: true, kind: true },
  });
  return rows.map((r) => ({
    lat: r.lat as number,
    lng: r.lng as number,
    city: r.city,
    country: r.country,
    kind: r.kind,
  }));
}
