"use server";

import { headers } from "next/headers";
import { revalidatePath } from "next/cache";
import { requireArea } from "./rbac";
import { setSetting } from "./settings";
import { clientIp } from "./rate-limit";
import { excludedIps } from "./analytics";

/**
 * Manage the analytics IP exclude-list — the "hide my own traffic" control. The
 * list feeds lib/analytics.ts (ipEx) so every visitor stat drops these IPs, so
 * the dashboard shows ACTUAL public traffic. Admin-only (fleet-adjacent, gated
 * on the same "platform" area as the rest of the analytics tooling).
 */

const KEY = "analytics_excluded_ips";
const IPV4 = /^\d{1,3}(\.\d{1,3}){3}$/;
const IPV6ish = /^[0-9a-fA-F:]{2,45}$/;

function valid(ip: string): boolean {
  const a = ip.trim();
  return IPV4.test(a) || (a.includes(":") && IPV6ish.test(a));
}

/** The admin's own current IP + the current exclude-list, for the panel. */
export async function analyticsExcludeState(): Promise<{ myIp: string; excluded: string[] }> {
  await requireArea("analytics");
  const myIp = clientIp(await headers());
  return { myIp, excluded: await excludedIps() };
}

export async function addExcludedIp(ip: string): Promise<{ error?: string; ok?: boolean }> {
  await requireArea("analytics");
  const clean = String(ip ?? "").trim();
  if (!valid(clean)) return { error: "Enter a valid IPv4 or IPv6 address." };
  const cur = await excludedIps();
  if (!cur.includes(clean)) cur.push(clean);
  await setSetting(KEY, cur.slice(0, 100).join(","));
  revalidatePath("/admin/visitors");
  return { ok: true };
}

export async function removeExcludedIp(ip: string): Promise<void> {
  await requireArea("analytics");
  const cur = (await excludedIps()).filter((x) => x !== ip);
  await setSetting(KEY, cur.join(","));
  revalidatePath("/admin/visitors");
}
