"use client";

import { useEffect, useRef } from "react";
import { usePathname } from "next/navigation";

/**
 * Invisible page-view beacon. Mount once in the marketing layout (kind default)
 * and once in the portal Shell with `kind="portal"`. On every client-side route
 * change it fires a best-effort POST to /api/track. Rapid repeats of the same
 * path are de-duped within the tab via sessionStorage so React strict-mode
 * double-mounts and quick back/forward navigation don't double-count.
 *
 * Beyond the raw pageview it now also captures the behaviour the audience/funnel
 * dashboard needs, all client-side and cookie-free here (the durable, consent-gated
 * visitor id is minted server-side in /api/track):
 *  - a per-TAB `sessionId` (sessionStorage, restarts after 30 min idle) so pageviews
 *    group into sessions for "avg time on site" and bounce rate,
 *  - an `isEntry` flag on the first pageview of a session (the landing page),
 *  - `utm_*` params off the landing URL, remembered for the whole session so every
 *    page attributes back to the ad/campaign that brought the visitor,
 *  - a per-pageview id (`pvid`) plus a dwell-time "close" beacon fired on navigation
 *    away and on pagehide, so each pageview gets a real time-on-page.
 */
export default function VisitTracker({ kind = "marketing" }: { kind?: "marketing" | "portal" }) {
  const pathname = usePathname();
  // The currently-open pageview whose dwell time we still owe a close beacon for.
  const openRef = useRef<{ pvid: string; start: number } | null>(null);

  useEffect(() => {
    if (typeof window === "undefined") return;
    const path = pathname || window.location.pathname || "/";

    // Dedupe: skip if we already tracked this exact path within the last 30s.
    const dkey = `nx_track:${kind}:${path}`;
    try {
      const last = Number(window.sessionStorage.getItem(dkey) ?? 0);
      if (Date.now() - last < 30_000) return;
      window.sessionStorage.setItem(dkey, String(Date.now()));
    } catch {
      /* private mode / storage disabled — just proceed without dedupe */
    }

    // --- Session id (per tab, 30-min idle window) + entry detection ---
    const SESSION_IDLE_MS = 30 * 60_000;
    let sessionId = "";
    let isEntry = false;
    let utm: { source?: string; medium?: string; campaign?: string } = {};
    try {
      const now = Date.now();
      const prevId = window.sessionStorage.getItem("nx_sid");
      const prevTs = Number(window.sessionStorage.getItem("nx_sid_ts") ?? 0);
      if (prevId && now - prevTs < SESSION_IDLE_MS) {
        sessionId = prevId;
        // Carry the session's captured campaign forward to every page.
        try {
          utm = JSON.parse(window.sessionStorage.getItem("nx_utm") ?? "{}");
        } catch {
          /* ignore malformed */
        }
      } else {
        // Fresh session: this pageview is the entry/landing hit.
        sessionId = genId();
        isEntry = true;
        const qs = new URLSearchParams(window.location.search);
        const src = qs.get("utm_source") ?? undefined;
        const med = qs.get("utm_medium") ?? undefined;
        const camp = qs.get("utm_campaign") ?? undefined;
        utm = {
          ...(src ? { source: src.slice(0, 120) } : {}),
          ...(med ? { medium: med.slice(0, 120) } : {}),
          ...(camp ? { campaign: camp.slice(0, 120) } : {}),
        };
        window.sessionStorage.setItem("nx_sid", sessionId);
        window.sessionStorage.setItem("nx_utm", JSON.stringify(utm));
      }
      window.sessionStorage.setItem("nx_sid_ts", String(now));
    } catch {
      // Storage disabled — still track the pageview, just without session grouping.
      sessionId = genId();
    }

    // Close out the previous pageview's dwell before opening this one (SPA nav).
    closeOpen();

    const pvid = genId();
    openRef.current = { pvid, start: Date.now() };

    try {
      fetch(`/api/track?k=${kind}`, {
        method: "POST",
        headers: { "content-type": "application/json" },
        body: JSON.stringify({
          path,
          referrer: document.referrer || null,
          sessionId,
          pvid,
          isEntry,
          utmSource: utm.source ?? null,
          utmMedium: utm.medium ?? null,
          utmCampaign: utm.campaign ?? null,
        }),
        keepalive: true,
      }).catch(() => {});
    } catch {
      /* fire-and-forget; never disrupt the page */
    }
    // pathname is the dependency; helpers are stable closures.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [pathname, kind]);

  // Close the last open pageview when the tab is actually going away.
  useEffect(() => {
    if (typeof window === "undefined") return;
    const onHide = () => closeOpen();
    window.addEventListener("pagehide", onHide);
    document.addEventListener("visibilitychange", () => {
      if (document.visibilityState === "hidden") closeOpen();
    });
    return () => window.removeEventListener("pagehide", onHide);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [kind]);

  /** Send the dwell time for the currently-open pageview, once. */
  function closeOpen() {
    const open = openRef.current;
    if (!open) return;
    openRef.current = null;
    const dur = Date.now() - open.start;
    if (dur < 250) return; // ignore instant bounces / strict-mode churn
    const body = JSON.stringify({ close: true, pvid: open.pvid, dur });
    try {
      // sendBeacon survives unload; fall back to keepalive fetch.
      if (navigator.sendBeacon) {
        navigator.sendBeacon(`/api/track?k=${kind}`, new Blob([body], { type: "application/json" }));
      } else {
        fetch(`/api/track?k=${kind}`, {
          method: "POST",
          headers: { "content-type": "application/json" },
          body,
          keepalive: true,
        }).catch(() => {});
      }
    } catch {
      /* best-effort */
    }
  }

  return null;
}

/** Small random id; prefers crypto.randomUUID, falls back for old browsers. */
function genId(): string {
  try {
    if (typeof crypto !== "undefined" && crypto.randomUUID) return crypto.randomUUID();
  } catch {
    /* ignore */
  }
  return `${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 10)}`;
}

