// ============================================================================
//  Behaviour + funnel — the "what do ad visitors actually DO" layer.
//  Feeds the admin audience dashboard (app/admin/audience). Everything below is
//  read-only, window-scoped and take-capped so it stays cheap as Visit grows.
// ============================================================================

/** Server statuses that mean a real machine was provisioned (funnel "deployed").
 *  Excludes attempts that never became a VM (PENDING/PROVISIONING/ERROR). */
export const DEPLOYED_STATUSES = [
  "RUNNING",
  "STOPPED",
  "SUSPENDED",
  "REINSTALLING",
  "DELETING",
] as const;

/** Cap on how many ids we pass into an `in` clause, to keep queries bounded. */
const ID_CAP = 20_000;

export type NewVsRecurring = {
  /** Distinct identified visitors (by visitorId) active in the window. */
  identified: number;
  /** Of those, first seen ON/AFTER the window start (brand-new). */
  newVisitors: number;
  /** Of those, seen on some earlier day too (recurring). */
  returningVisitors: number;
};

/**
 * New vs recurring visitors over the trailing `days` window. Uses the stable
 * `visitorId` cookie, so it recognises the same person across sessions/IPs —
 * the thing IP-based "unique visitors" cannot do. Opted-out visitors (null
 * visitorId) are simply absent here; they still count in the IP-based uniques.
 */
export async function newVsRecurring(days = 7): Promise<NewVsRecurring> {
  const since = new Date(Date.now() - days * DAY);
  const inWindow = await db.visit.findMany({
    where: { createdAt: { gte: since }, visitorId: { not: null }, ...(await ipEx()) },
    distinct: ["visitorId"],
    select: { visitorId: true },
    take: ID_CAP,
  });
  const ids = inWindow.map((r) => r.visitorId as string);
  if (ids.length === 0) return { identified: 0, newVisitors: 0, returningVisitors: 0 };

  // Which of those visitors we had already seen BEFORE this window = recurring.
  const earlier = await db.visit.findMany({
    where: { visitorId: { in: ids }, createdAt: { lt: since } },
    distinct: ["visitorId"],
    select: { visitorId: true },
    take: ID_CAP,
  });
  const returningVisitors = earlier.length;
  return {
    identified: ids.length,
    newVisitors: ids.length - returningVisitors,
    returningVisitors,
  };
}

export type TimeStats = {
  sessions: number;
  /** Average session dwell (ms) — the "avg time on site" headline. */
  avgSessionMs: number;
  /** Average pageviews per session. */
  avgPageviews: number;
  /** Share of sessions that were a single pageview (0..1). */
  bounceRate: number;
};

/**
 * Session-level engagement over the window: avg time on site, pages/session and
 * bounce rate. Dwell comes from the per-pageview close beacons; a session's time
 * is the sum of its pages' dwell. Sessions with no measured dwell still count for
 * pages/session and bounce, they just contribute 0 to the time average.
 */
export async function visitorTimeStats(days = 7): Promise<TimeStats> {
  const since = new Date(Date.now() - days * DAY);
  const rows = await db.visit.findMany({
    where: { createdAt: { gte: since }, sessionId: { not: null }, ...(await ipEx()) },
    select: { sessionId: true, durationMs: true },
    take: 50_000,
    orderBy: { createdAt: "desc" },
  });
  if (rows.length === 0)
    return { sessions: 0, avgSessionMs: 0, avgPageviews: 0, bounceRate: 0 };

  const perSession = new Map<string, { ms: number; views: number }>();
  for (const r of rows) {
    const key = r.sessionId as string;
    const cur = perSession.get(key) ?? { ms: 0, views: 0 };
    cur.views += 1;
    cur.ms += r.durationMs ?? 0;
    perSession.set(key, cur);
  }
  const sessions = perSession.size;
  let totalMs = 0;
  let totalViews = 0;
  let bounces = 0;
  for (const s of perSession.values()) {
    totalMs += s.ms;
    totalViews += s.views;
    if (s.views <= 1) bounces += 1;
  }
  return {
    sessions,
    avgSessionMs: Math.round(totalMs / sessions),
    avgPageviews: totalViews / sessions,
    bounceRate: bounces / sessions,
  };
}

/** Most-viewed paths over the window (what visitors look at). */
export async function topPages(days = 7, limit = 10): Promise<Counted[]> {
  const since = new Date(Date.now() - days * DAY);
  const grp = await db.visit.groupBy({
    by: ["path"],
    where: { createdAt: { gte: since }, ...(await ipEx()) },
    _count: { _all: true },
  });
  return grp
    .map((g) => ({ label: g.path, count: g._count._all }))
    .sort((a, b) => b.count - a.count)
    .slice(0, limit);
}

/** Top landing/entry pages over the window (where sessions begin). */
export async function topEntryPages(days = 7, limit = 8): Promise<Counted[]> {
  const since = new Date(Date.now() - days * DAY);
  const grp = await db.visit.groupBy({
    by: ["path"],
    where: { createdAt: { gte: since }, isEntry: true, ...(await ipEx()) },
    _count: { _all: true },
  });
  return grp
    .map((g) => ({ label: g.path, count: g._count._all }))
    .sort((a, b) => b.count - a.count)
    .slice(0, limit);
}

/** Top UTM sources over the window — which ad/source is actually sending traffic.
 *  Labels combine source + medium so "google / cpc" reads distinctly from
 *  "google / organic". Visits with no utm_source are omitted. */
export async function topUtmSources(days = 30, limit = 8): Promise<Counted[]> {
  const since = new Date(Date.now() - days * DAY);
  const grp = await db.visit.groupBy({
    by: ["utmSource", "utmMedium"],
    where: { createdAt: { gte: since }, utmSource: { not: null }, ...(await ipEx()) },
    _count: { _all: true },
  });
  return grp
    .map((g) => ({
      label: g.utmMedium ? `${g.utmSource} / ${g.utmMedium}` : (g.utmSource as string),
      count: g._count._all,
    }))
    .sort((a, b) => b.count - a.count)
    .slice(0, limit);
}

/** Top UTM campaigns over the window. */
export async function topUtmCampaigns(days = 30, limit = 8): Promise<Counted[]> {
  const since = new Date(Date.now() - days * DAY);
  const grp = await db.visit.groupBy({
    by: ["utmCampaign"],
    where: { createdAt: { gte: since }, utmCampaign: { not: null }, ...(await ipEx()) },
    _count: { _all: true },
  });
  return grp
    .map((g) => ({ label: g.utmCampaign as string, count: g._count._all }))
    .sort((a, b) => b.count - a.count)
    .slice(0, limit);
}

export type Funnel = {
  /** Distinct IP visitors in the window (top of funnel — consent-independent). */
  visitors: number;
  /** Accounts created in the window. */
  signups: number;
  /** Of those signups, how many deployed at least one real server. */
  deployed: number;
  /** Of those signups, how many deployed a PAID (non-free) server. */
  paid: number;
};

/**
 * The signup → deploy funnel over the window. Visitors is IP-distinct (works even
 * for opted-out traffic and matches the visitor page's "unique visitors"). Signups
 * and deploys are scoped to accounts CREATED in the window, so the deploy/paid
 * conversion is measured against the same cohort — a clean "of the people who
 * signed up this period, how far did they get" read for the ad spend.
 */
export async function signupDeployFunnel(days = 30): Promise<Funnel> {
  const since = new Date(Date.now() - days * DAY);

  const [ipRows, signupUsers] = await Promise.all([
    db.visit.findMany({
      where: { createdAt: { gte: since }, ...(await ipEx()) },
      distinct: ["ip"],
      select: { ip: true },
      take: ID_CAP,
    }),
    db.user.findMany({
      where: { createdAt: { gte: since } },
      select: { id: true },
      take: ID_CAP,
    }),
  ]);

  const signupIds = signupUsers.map((u) => u.id);
  if (signupIds.length === 0) {
    return { visitors: ipRows.length, signups: 0, deployed: 0, paid: 0 };
  }

  const [deployedRows, paidRows] = await Promise.all([
    db.server.findMany({
      where: { userId: { in: signupIds }, status: { in: [...DEPLOYED_STATUSES] } },
      distinct: ["userId"],
      select: { userId: true },
    }),
    db.server.findMany({
      where: {
        userId: { in: signupIds },
        isFree: false,
        status: { in: [...DEPLOYED_STATUSES] },
      },
      distinct: ["userId"],
      select: { userId: true },
    }),
  ]);

  return {
    visitors: ipRows.length,
    signups: signupIds.length,
    deployed: deployedRows.length,
    paid: paidRows.length,
  };
}

export type VisitorDayPoint = {
  /** UTC midnight of the day. */
  date: Date;
  pageviews: number;
  uniqueVisitors: number;
  newVisitors: number;
  returningVisitors: number;
  sessions: number;
  avgSessionMs: number;
};

/**
 * Compute a single UTC day's visitor metrics directly from the Visit log. Shared
 * by the worker rollup (which persists it to VisitorDaily) and the audience page
 * (which calls it for TODAY, to overlay live freshness on the stored rollup).
 */
export async function computeVisitorDay(dayStart: Date, dayEnd: Date): Promise<VisitorDayPoint> {
  const ex = await ipEx();
  const where = { createdAt: { gte: dayStart, lte: dayEnd }, ...ex };

  const [pageviews, sessionRows, visitorRows] = await Promise.all([
    db.visit.count({ where }),
    db.visit.findMany({
      where: { ...where, sessionId: { not: null } },
      select: { sessionId: true, durationMs: true },
      take: 50_000,
    }),
    db.visit.findMany({
      where: { ...where, visitorId: { not: null } },
      distinct: ["visitorId"],
      select: { visitorId: true },
      take: ID_CAP,
    }),
  ]);

  // Sessions + dwell.
  const perSession = new Map<string, number>();
  for (const r of sessionRows) {
    const k = r.sessionId as string;
    perSession.set(k, (perSession.get(k) ?? 0) + (r.durationMs ?? 0));
  }
  const sessions = perSession.size;
  let totalMs = 0;
  for (const ms of perSession.values()) totalMs += ms;

  // Unique visitors: identified by cookie, plus IP-only for opted-out traffic.
  const ipOnly = await db.visit.findMany({
    where: { ...where, visitorId: null },
    distinct: ["ip"],
    select: { ip: true },
    take: ID_CAP,
  });
  const uniqueVisitors = visitorRows.length + ipOnly.length;

  // New vs returning among the identified visitors seen today.
  const ids = visitorRows.map((r) => r.visitorId as string);
  let returningVisitors = 0;
  if (ids.length > 0) {
    const earlier = await db.visit.findMany({
      where: { visitorId: { in: ids }, createdAt: { lt: dayStart } },
      distinct: ["visitorId"],
      select: { visitorId: true },
      take: ID_CAP,
    });
    returningVisitors = earlier.length;
  }

  return {
    date: dayStart,
    pageviews,
    uniqueVisitors,
    newVisitors: ids.length - returningVisitors,
    returningVisitors,
    sessions,
    avgSessionMs: sessions > 0 ? Math.round(totalMs / sessions) : 0,
  };
}

/**
 * The last `days` days of the VisitorDaily rollup, oldest-first, with any missing
 * days filled in as zero rows so the trend chart has a continuous x-axis. Powers
 * the audience dashboard's trend without scanning the raw Visit log.
 */
export async function readVisitorDailySeries(days = 30): Promise<VisitorDayPoint[]> {
  const today = new Date();
  const start = new Date(Date.UTC(today.getUTCFullYear(), today.getUTCMonth(), today.getUTCDate()));
  start.setUTCDate(start.getUTCDate() - (days - 1));

  const rows = await db.visitorDaily.findMany({
    where: { date: { gte: start } },
    orderBy: { date: "asc" },
  });
  const byKey = new Map<string, (typeof rows)[number]>();
  for (const r of rows) byKey.set(r.date.toISOString().slice(0, 10), r);

  const out: VisitorDayPoint[] = [];
  for (let i = 0; i < days; i++) {
    const d = new Date(start);
    d.setUTCDate(start.getUTCDate() + i);
    const hit = byKey.get(d.toISOString().slice(0, 10));
    out.push(
      hit
        ? {
            date: d,
            pageviews: hit.pageviews,
            uniqueVisitors: hit.uniqueVisitors,
            newVisitors: hit.newVisitors,
            returningVisitors: hit.returningVisitors,
            sessions: hit.sessions,
            avgSessionMs: hit.sessions > 0 ? Math.round(Number(hit.totalSessionMs) / hit.sessions) : 0,
          }
        : {
            date: d,
            pageviews: 0,
            uniqueVisitors: 0,
            newVisitors: 0,
            returningVisitors: 0,
            sessions: 0,
            avgSessionMs: 0,
          }
    );
  }
  return out;
}

/** Whether the VisitorDaily rollup has any rows yet (else the page computes live). */
export async function hasVisitorDailyRows(): Promise<boolean> {
  return (await db.visitorDaily.count()) > 0;
}

