145	export function Donut({
146	  segments,
147	  size = 132,
148	  thickness = 14,
149	  centerLabel,
150	  centerSub,
151	}: {
152	  segments: { value: number; color: string }[];
153	  size?: number;
154	  thickness?: number;
155	  centerLabel?: string;
156	  centerSub?: string;
157	}) {
158	  const total = segments.reduce((n, s) => n + s.value, 0) || 1;
159	  const r = (size - thickness) / 2;
160	  const c = 2 * Math.PI * r;
161	  let offset = 0;
162	  return (
163	    <svg width={size} height={size} viewBox={`0 0 ${size} ${size}`}>
164	      <circle cx={size / 2} cy={size / 2} r={r} fill="none" stroke="rgba(255,255,255,0.06)" strokeWidth={thickness} />
