189	      )}
190	      {centerSub && (
191	        <text x="50%" y="62%" textAnchor="middle" fontSize="10" fill="#64748b">
192	          {centerSub}
193	        </text>
194	      )}
195	    </svg>
196	  );
197	}
198	
199	export function MeterBar({
200	  value,
201	  max,
202	  color = "#6f47f5",
203	  className = "",
204	}: {
205	  value: number;
206	  max: number;
207	  color?: string;
208	  className?: string;
209	}) {
210	  const pct = Math.min(100, (value / (max || 1)) * 100);
211	  return (
212	    <div className={`h-2 w-full rounded-full bg-white/[0.06] ${className}`}>
213	      <div
214	        className="h-2 rounded-full transition-all duration-500"
215	        style={{ width: `${pct}%`, background: `linear-gradient(90deg, #3b82f6, ${color})` }}
216	      />
217	    </div>
218	  );
219	}
