import Link from "next/link";
import { requireArea } from "@/lib/rbac";
import { PageHeader, StatCard } from "@/components/ui/primitives";
import { AreaChart, Donut, MeterBar } from "@/components/ui/charts";
import { RankedList } from "@/components/admin/VisitorStats";
import {
  newVsRecurring,
  visitorTimeStats,
  topPages,
  topEntryPages,
  topReferrers,
  topUtmSources,
  topUtmCampaigns,
  signupDeployFunnel,
  uniqueVisitors,
  viewsInWindow,
  readVisitorDailySeries,
  computeVisitorDay,
} from "@/lib/analytics";

export const dynamic = "force-dynamic";

const WINDOWS = [7, 30, 90] as const;
type Win = (typeof WINDOWS)[number];

/** Human "2m 34s" / "48s" from milliseconds. */
function fmtDuration(ms: number): string {
  const s = Math.round(ms / 1000);
  if (s < 60) return `${s}s`;
  const m = Math.floor(s / 60);
  const rem = s % 60;
  return rem ? `${m}m ${rem}s` : `${m}m`;
}

function pct(n: number, d: number): string {
  if (d <= 0) return "0%";
  return `${((n / d) * 100).toFixed(n / d >= 0.1 ? 0 : 1)}%`;
}

export default async function AudiencePage({
  searchParams,
}: {
  searchParams: Promise<{ days?: string }>;
}) {
  await requireArea("analytics");

  const sp = await searchParams;
  const days: Win = WINDOWS.includes(Number(sp.days) as Win) ? (Number(sp.days) as Win) : 30;

  const [
    nvr,
    time,
    pages,
    entryPages,
    referrers,
    utmSources,
    utmCampaigns,
    funnel,
    uniques,
    views,
    series,
  ] = await Promise.all([
    newVsRecurring(days),
    visitorTimeStats(days),
    topPages(days, 10),
    topEntryPages(days, 8),
    topReferrers(days, 8),
    topUtmSources(days, 8),
    topUtmCampaigns(days, 8),
    signupDeployFunnel(days),
    uniqueVisitors(days),
    viewsInWindow(days),
    readVisitorDailySeries(30),
  ]);

  // Overlay a live "today" on the stored rollup so the trend's last point is fresh
  // even between the worker's 15-min rollups.
  const now = new Date();
  const todayStart = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate()));
  const todayLive = await computeVisitorDay(todayStart, now);
  if (series.length > 0) series[series.length - 1] = todayLive;

  const pvSeries = series.map((p) => p.pageviews);
  const uvSeries = series.map((p) => p.uniqueVisitors);
  const xLabels = series
    .map((p, i) => (i % 6 === 0 || i === series.length - 1 ? `${p.date.getUTCMonth() + 1}/${p.date.getUTCDate()}` : ""))
    .filter(Boolean);

  // Funnel steps, each as a share of the top (visitors).
  const steps = [
    { label: "Visitors", value: funnel.visitors, color: "#22d3ee", note: `unique IPs · ${days}d` },
    { label: "Signups", value: funnel.signups, color: "#3b82f6", note: `accounts created · ${days}d` },
    { label: "Deployed a server", value: funnel.deployed, color: "#8a70fb", note: "of those signups" },
    { label: "Paid deploy", value: funnel.paid, color: "#34d399", note: "non-free server" },
  ];
  const funnelMax = Math.max(...steps.map((s) => s.value), 1);

  return (
    <div className="space-y-6">
      <PageHeader
        title="Audience & funnel"
        sub="What ad visitors do on the site — new vs recurring, time on site, top pages, sources, and the signup → deploy funnel."
      />

      {/* Window selector */}
      <div className="flex gap-2">
        {WINDOWS.map((w) => (
          <Link
            key={w}
            href={`/admin/audience?days=${w}`}
            className={`rounded-lg border px-3 py-1.5 text-sm ${
              w === days
                ? "border-brand-400/60 bg-brand-500/15 text-brand-200"
                : "border-white/[0.08] text-slate-400 hover:text-slate-200"
            }`}
          >
            {w}d
          </Link>
        ))}
      </div>

      {/* Headline */}
      <div className="grid grid-cols-2 gap-4 xl:grid-cols-4">
        <StatCard label={`Unique visitors · ${days}d`} value={String(uniques)} delta={`${views} pageviews`} />
        <StatCard
          label="Recurring visitors"
          value={String(nvr.returningVisitors)}
          delta={
            nvr.identified > 0
              ? `${pct(nvr.returningVisitors, nvr.identified)} of ${nvr.identified} identified`
              : "no identified visitors yet"
          }
          deltaGood={nvr.returningVisitors > 0}
        />
        <StatCard
          label="Avg time on site"
          value={time.sessions > 0 ? fmtDuration(time.avgSessionMs) : "—"}
          delta={time.sessions > 0 ? `${time.avgPageviews.toFixed(1)} pages/session` : "no sessions yet"}
        />
        <StatCard
          label="Bounce rate"
          value={time.sessions > 0 ? pct(Math.round(time.bounceRate * time.sessions), time.sessions) : "—"}
          delta={`${time.sessions} sessions · ${days}d`}
          deltaGood={time.bounceRate < 0.6}
        />
      </div>

      {/* Trend + new vs recurring */}
      <div className="grid gap-4 xl:grid-cols-3">
        <div className="card xl:col-span-2">
          <h2 className="mb-1 font-semibold">Traffic trend</h2>
          <p className="mb-3 text-xs text-slate-500">Pageviews and unique visitors per day, last 30 days.</p>
          <AreaChart
            id="aud-trend"
            height={220}
            series={[
              { name: "Pageviews", data: pvSeries, color: "#8a70fb" },
              { name: "Unique visitors", data: uvSeries, color: "#22d3ee" },
            ]}
            xLabels={xLabels}
            yLabel={(v) => v.toFixed(0)}
          />
          <div className="mt-2 flex gap-4 text-xs text-slate-400">
            <span className="flex items-center gap-1.5">
              <span className="h-2 w-2 rounded-full" style={{ background: "#8a70fb" }} /> Pageviews
            </span>
            <span className="flex items-center gap-1.5">
              <span className="h-2 w-2 rounded-full" style={{ background: "#22d3ee" }} /> Unique visitors
            </span>
          </div>
        </div>

        <div className="card">
          <h2 className="mb-1 font-semibold">New vs recurring</h2>
          <p className="mb-4 text-xs text-slate-500">Identified visitors (cookie) · last {days} days.</p>
          {nvr.identified === 0 ? (
            <p className="py-8 text-center text-sm text-slate-500">
              No identified visitors yet — recurring vs new appears once traffic (with cookies allowed) accrues.
            </p>
          ) : (
            <div className="flex items-center gap-6">
              <Donut
                segments={[
                  { value: nvr.newVisitors, color: "#3b82f6" },
                  { value: nvr.returningVisitors, color: "#34d399" },
                ]}
                centerLabel={String(nvr.identified)}
                centerSub="visitors"
              />
              <ul className="space-y-2 text-sm">
                <li className="flex items-center gap-2">
                  <span className="h-2.5 w-2.5 rounded-full" style={{ background: "#3b82f6" }} />
                  <span>New</span>
                  <span className="text-xs text-slate-500">
                    {nvr.newVisitors} · {pct(nvr.newVisitors, nvr.identified)}
                  </span>
                </li>
                <li className="flex items-center gap-2">
                  <span className="h-2.5 w-2.5 rounded-full" style={{ background: "#34d399" }} />
                  <span>Recurring</span>
                  <span className="text-xs text-slate-500">
                    {nvr.returningVisitors} · {pct(nvr.returningVisitors, nvr.identified)}
                  </span>
                </li>
              </ul>
            </div>
          )}
        </div>
      </div>

      {/* Funnel */}
      <div className="card">
        <h2 className="mb-1 font-semibold">Signup → deploy funnel</h2>
        <p className="mb-4 text-xs text-slate-500">
          How far the last {days} days of traffic gets toward a deployed server. Each step shows conversion from the
          step above.
        </p>
        <div className="space-y-4">
          {steps.map((s, i) => {
            const prev = i === 0 ? s.value : steps[i - 1].value;
            return (
              <div key={s.label}>
                <div className="mb-1 flex items-baseline justify-between text-sm">
                  <span className="font-medium">{s.label}</span>
                  <span className="tabular-nums">
                    <span className="font-semibold">{s.value.toLocaleString()}</span>
                    {i > 0 && (
                      <span className="ml-2 text-xs text-slate-500">{pct(s.value, prev)} of prev</span>
                    )}
                    <span className="ml-2 text-xs text-slate-500">{s.note}</span>
                  </span>
                </div>
                <MeterBar value={s.value} max={funnelMax} color={s.color} />
              </div>
            );
          })}
        </div>
      </div>

      {/* Sources */}
      <div className="grid gap-4 xl:grid-cols-3">
        <RankedList
          title="Top UTM sources"
          sub={`Tagged ad/source traffic · last ${days} days`}
          items={utmSources}
          emptyLabel="No utm_source-tagged visits yet — tag your ad links (?utm_source=…) to attribute them."
        />
        <RankedList
          title="Top UTM campaigns"
          sub={`By utm_campaign · last ${days} days`}
          items={utmCampaigns}
          emptyLabel="No utm_campaign-tagged visits yet."
        />
        <RankedList
          title="Top referrers"
          sub={`External sources · last ${days} days`}
          items={referrers}
          emptyLabel="No external referrers yet — traffic is direct."
        />
      </div>

      {/* Content */}
      <div className="grid gap-4 xl:grid-cols-2">
        <RankedList
          title="Top pages"
          sub={`Most-viewed paths · last ${days} days`}
          items={pages}
          emptyLabel="No pageviews yet."
        />
        <RankedList
          title="Top landing pages"
          sub={`Where sessions begin · last ${days} days`}
          items={entryPages}
          emptyLabel="No entry pages recorded yet."
        />
      </div>
    </div>
  );
}

